/**
 * Query Categories API
 * Fetches booking service categories from Wix Bookings
 *
 * @module API/QueryCategories
 */
import { categoriesV2 } from '@wix/bookings';
/**
 * Category type from the Wix Bookings Categories V2 API
 */
export type Category = categoriesV2.Category;
/**
 * Result from querying categories
 */
export interface QueryCategoriesResult {
    /** Array of booking service categories */
    categories: Category[];
}
/**
 * Query all booking service categories.
 * Returns an array of categories sorted by creation date (ascending).
 *
 * @returns Promise resolving to categories array
 *
 * @example
 * ```ts
 * const { categories } = await queryCategories();
 *
 * categories.forEach(category => {
 *   console.log(category.name, category._id);
 * });
 * ```
 */
export declare function queryCategories(): Promise<QueryCategoriesResult>;
